import React, { createContext, useContext, useReducer, useEffect } from 'react';
import { useLocalStorage } from '../hooks/useLocalStorage';

const DonorContext = createContext();

const initialState = {
    donors: [],
    agentAssignments: [],
    loading: false,
    error: null
};

function donorReducer(state, action) {
    switch (action.type) {
        case 'ADD_DONOR':
            return {
                ...state,
                donors: [...state.donors, action.payload]
            };
        case 'SET_DONORS':
            return {
                ...state,
                donors: action.payload
            };
        case 'UPDATE_DONOR':
            return {
                ...state,
                donors: state.donors.map(donor =>
                    donor.id === action.payload.id ? action.payload : donor
                )
            };
        case 'DELETE_DONOR':
            return {
                ...state,
                donors: state.donors.filter(donor => donor.id !== action.payload)
            };
        case 'SET_AGENT_ASSIGNMENTS':
            return {
                ...state,
                agentAssignments: action.payload
            };
        case 'SET_LOADING':
            return {
                ...state,
                loading: action.payload
            };
        case 'SET_ERROR':
            return {
                ...state,
                error: action.payload
            };
        default:
            return state;
    }
}

export const DonorProvider = ({ children }) => {
    const [storedDonors, setStoredDonors] = useLocalStorage('donors', []);
    const [storedAssignments, setStoredAssignments] = useLocalStorage('agentAssignments', []);

    const [state, dispatch] = useReducer(donorReducer, {
        ...initialState,
        donors: storedDonors,
        agentAssignments: storedAssignments
    });

    // Sync state with localStorage whenever donors or assignments change
    useEffect(() => {
        setStoredDonors(state.donors);
    }, [state.donors, setStoredDonors]);

    useEffect(() => {
        setStoredAssignments(state.agentAssignments);
    }, [state.agentAssignments, setStoredAssignments]);

    // Add a new donor
    const addDonor = (donor) => {
        const newDonor = {
            ...donor,
            id: Date.now().toString(),
            createdAt: new Date().toISOString(),
            status: 'pending'
        };

        dispatch({ type: 'ADD_DONOR', payload: newDonor });
        return newDonor;
    };

    // Update donor status and information
    const updateDonor = (donor) => {
        dispatch({ type: 'UPDATE_DONOR', payload: donor });
    };

    // Delete a donor
    const deleteDonor = (id) => {
        dispatch({ type: 'DELETE_DONOR', payload: id });
    };

    // Split donors among agents
    const splitDonors = (agentCount) => {
        if (!agentCount || agentCount < 1) return;

        const pendingDonors = state.donors.filter(donor =>
            donor.status === 'pending' && donor.type === 'sheep'
        );

        // Group cow donors separately (they need 7 people per cow)
        const cowDonors = state.donors.filter(donor => donor.type === 'cow');
        const cowGroups = [];

        for (let i = 0; i < Math.floor(cowDonors.length / 7); i++) {
            cowGroups.push(cowDonors.slice(i * 7, (i + 1) * 7));
        }

        // Calculate how many donors each agent gets
        const donorsPerAgent = Math.ceil(pendingDonors.length / agentCount);

        // Create agent assignments
        const assignments = [];

        for (let i = 0; i < agentCount; i++) {
            const start = i * donorsPerAgent;
            const end = Math.min(start + donorsPerAgent, pendingDonors.length);

            assignments.push({
                id: `agent-${i + 1}`,
                name: `Agent ${i + 1}`,
                donors: pendingDonors.slice(start, end).map(d => d.id),
                cowGroups: i < cowGroups.length ? [cowGroups[i].map(d => d.id)] : []
            });
        }

        // Distribute remaining cow groups
        for (let i = agentCount; i < cowGroups.length; i++) {
            const agentIndex = i % agentCount;
            assignments[agentIndex].cowGroups.push(
                cowGroups[i].map(d => d.id)
            );
        }

        dispatch({ type: 'SET_AGENT_ASSIGNMENTS', payload: assignments });
        return assignments;
    };

    // Mark donor as done with uploaded media
    const markDonorAsDone = (id, media) => {
        const donor = state.donors.find(d => d.id === id);
        if (!donor) return;

        const updatedDonor = {
            ...donor,
            status: 'sending', // Will be updated to 'done' after sync
            media,
            completedAt: new Date().toISOString()
        };

        updateDonor(updatedDonor);
        return updatedDonor;
    };

    // Get donors for a specific agent
    const getDonorsByAgent = (agentId) => {
        const assignment = state.agentAssignments.find(a => a.id === agentId);
        if (!assignment) return [];

        const sheepDonors = assignment.donors.map(id =>
            state.donors.find(d => d.id === id)
        ).filter(Boolean);

        const cowDonors = assignment.cowGroups.flatMap(group =>
            group.map(id => state.donors.find(d => d.id === id))
        ).filter(Boolean);

        return { sheepDonors, cowDonors };
    };

    return (
        <DonorContext.Provider value={{
            donors: state.donors,
            loading: state.loading,
            error: state.error,
            agentAssignments: state.agentAssignments,
            addDonor,
            updateDonor,
            deleteDonor,
            splitDonors,
            markDonorAsDone,
            getDonorsByAgent
        }}>
            {children}
        </DonorContext.Provider>
    );
};

export const useDonors = () => useContext(DonorContext);
